'use client';

import React, { useState } from 'react';
import CarouselHero from './components/Carousel';
import NovedadesCarousel from './components/NovedadesCarousel';
import ProductGrid from './components/ProductGrid';
import HeaderNav from './components/HeaderNav';
import NavigationControls from './components/NavigationControls';
import TrustBanner from './components/TrustBanner';
import AlertBanner from './components/AlertBanner';
import { useCartStore, NewCartItem } from '../src/lib/useCartStore';

export default function Home() {
  const addToCart = useCartStore((state) => state.addToCart);
  const cartItems = useCartStore((state) => state.cart);  const removeFromCart = useCartStore((state) => state.removeItem);
  const [lastAdded, setLastAdded] = useState<string | null>(null);
  const [isDistributor, setIsDistributor] = useState<boolean>(false);
  const [isDistributorModalOpen, setIsDistributorModalOpen] = useState<boolean>(false);

  const handleAddToCart = (item: NewCartItem) => {
    addToCart(item);
    setLastAdded(item.product_title);
    setTimeout(() => setLastAdded(null), 3500);
  };

  return (
    <main style={{ backgroundColor: '#fdfcf1', minHeight: '100vh' }}>
      <AlertBanner />
      <HeaderNav 
        cartItems={cartItems.map(i => ({ id: i.product_id, title: i.product_title, price: String(i.unit_price), img: i.img_url || '' }))}
        onRemoveFromCart={(index) => {
          const itemToRemove = cartItems[index];
          if (itemToRemove) {
            removeFromCart(itemToRemove.product_id as any);
          }
        }}
        isDistributor={isDistributor}
        onOpenDistributorModal={() => setIsDistributorModalOpen(true)}
        onLogoutDistributor={() => setIsDistributor(false)}
      />
      <NavigationControls lastAddedProduct={lastAdded} />
      <CarouselHero />
      <NovedadesCarousel 
        onAddToCart={handleAddToCart} 
        isDistributor={isDistributor} 
      />
      
      <ProductGrid 
        onAddToCart={handleAddToCart} 
        isDistributor={isDistributor}
        onOpenDistributorModal={() => setIsDistributorModalOpen(true)}
      />

      {/* Modal simulado de acceso/registro de distribuidores */}
      {isDistributorModalOpen && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
          <div style={{ background: '#fff', padding: '2rem', borderRadius: '12px', maxWidth: '400px', width: '100%', position: 'relative' }}>
            <button onClick={() => setIsDistributorModalOpen(false)} style={{ position: 'absolute', top: '12px', right: '12px', border: 'none', background: 'none', cursor: 'pointer', fontSize: '1.2rem' }}>✕</button>
            <h3 style={{ marginBottom: '1rem', fontWeight: 'bold' }}>Portal de Distribuidores</h3>
            <p style={{ fontSize: '0.85rem', color: '#64748b', marginBottom: '1.5rem' }}>
              Inicia sesión con tus credenciales de mayorista para acceder a precios especiales y catálogo exclusivo.
            </p>
            <button 
              onClick={() => {
                setIsDistributor(true);
                setIsDistributorModalOpen(false);
              }}
              style={{ width: '100%', padding: '10px', background: '#16a34a', color: '#fff', border: 'none', borderRadius: '8px', fontWeight: 600, cursor: 'pointer' }}
            >
              Simular Acceso Mayorista
            </button>
          </div>
        </div>
      )}
    </main>
  );
}